pub struct Route {
    pub ref_count: usize,
    pub freed: bool,
}

impl Route {
    // Unprotected initial reference acquisition
    pub fn acquire_ref(&mut self) {
        if self.freed {
            panic!("Use after free!");
        }
        self.ref_count += 1;
    }
}
